<?php
require_once 'includes/config.php'; require_admin(); require_once 'includes/export_pdf.php';
$name=trim($_GET['name']??''); $class=(int)($_GET['class']??0); $gender=trim($_GET['gender']??''); $format=$_GET['format']??'csv';
$sql="SELECT t.id,t.full_name,t.username,t.email,t.gender,t.status,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(c.ClassName,' - ',c.Section) ORDER BY c.ClassName SEPARATOR ', '),'Unassigned') assigned_classes FROM teachers t LEFT JOIN teacher_class_assignments a ON a.teacher_id=t.id LEFT JOIN tblclasses c ON c.id=a.class_id WHERE 1=1"; $p=[];
if($name!==''){$sql.=" AND t.full_name LIKE :name";$p[':name']="%$name%";} if($gender!==''){$sql.=" AND t.gender=:gender";$p[':gender']=$gender;} if($class){$sql.=" AND EXISTS(SELECT 1 FROM teacher_class_assignments af WHERE af.teacher_id=t.id AND af.class_id=:class)";$p[':class']=$class;}
$sql.=" GROUP BY t.id ORDER BY t.full_name"; $q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
if($format==='pdf'){srms_pdf_download('teachers-export.pdf','Registered Teachers',[['key'=>'full_name','label'=>'Teacher','width'=>145],['key'=>'username','label'=>'Username','width'=>100],['key'=>'email','label'=>'Email','width'=>145],['key'=>'gender','label'=>'Gender','width'=>65],['key'=>'assigned_classes','label'=>'Assigned Classes','width'=>230],['key'=>'status_text','label'=>'Status','width'=>70]],array_map(function($r){$r['status_text']=$r['status']?'Active':'Inactive';return $r;},$rows));}
header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="teachers-export.csv"');$out=fopen('php://output','w');fputcsv($out,['Teacher','Username','Email','Gender','Assigned Classes','Status']);foreach($rows as $r)fputcsv($out,[$r['full_name'],$r['username'],$r['email'],$r['gender'],$r['assigned_classes'],$r['status']?'Active':'Inactive']);exit;
